function guestCount(m){return guestGroups(m).reduce((n,g)=>n+(guestWeight(g)>0?(g.adults||0)+(g.kids||0):0),0)}
function guestShort(m){const live=guestGroups(m).filter((g:any)=>guestWeight(g)>0),a=live.reduce((n:number,g:any)=>n+(g.adults||0),0),k=live.reduce((n:number,g:any)=>n+(g.kids||0),0),parts=[];if(a)parts.push(tr(`${a} khách`,`${a} guest${a>1?'s':''}`));if(k)parts.push(tr(`${k} bé`,`${k} child${k>1?'ren':''}`));return parts.join(', ')}
function guestNames(m){return guestGroups(m).filter((g:any)=>g.name).map((g:any)=>g.invite?`${g.name} (${rsvpLabel(g).split(' · ')[0]})`:g.name)}
function guestGroupShort(g){const p=[];if(g.adults)p.push(tr(`${g.adults} lớn`,`${g.adults} adult${g.adults>1?'s':''}`));if(g.kids)p.push(tr(`${g.kids} bé`,`${g.kids} child${g.kids>1?'ren':''}`));return p.join(', ')}
function guestLine(date,type,m){if(!guestGroups(m).length)return '';const names=guestNames(m);return `<div class="meal-guests"><button class="text-btn meal-guest-line" type="button" data-fm="guests" data-date="${esc(date)}" data-type="${esc(type)}"${m.cooked?' disabled':''}>${tr('Khách','Guests')}: ${esc(guestShort(m)||tr('không ai đến','nobody coming'))}${names.length?` · <span data-user-content>${esc(names.join(', '))}</span>`:''}</button></div>`}
// v1.7.12: short weekday in the chosen language (dayName is Vietnamese and option lists are not translated afterwards)
function dayShort(d:string){return typeof appLanguage!=='undefined'&&appLanguage==='en'?new Intl.DateTimeFormat('en-AU',{weekday:'short',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z')):dayName(d,true)}
let guestDraft:{groups:any[]}|null=null;
// the week menu's “Có khách” opens on the next meal that is not cooked yet (from today, or from the day being looked at)
function guestNextMeal(from:string){const start=from<sydneyDate()?sydneyDate():from;for(let i=0;i<14;i++){const d=addDays(start,i),day=ensureWeek(state,planStartOf(state,d)).days[d];for(const t of MEAL_TYPES)if(day&&day[t]&&fmMealOn(day,t)&&!day[t].cooked)return{date:d,type:t}}return{date:start,type:'dinner'}}
const guestMealTypes=(date:string)=>{const day=mealAt(state,date,'dinner')?ensureWeek(state,planStartOf(state,date)).days[date]:null;return MEAL_TYPES.filter(t=>!day||fmMealOn(day,t))};
function guestRange(){const v=(n:string)=>(document.querySelector(`#modal-root [name="${n}"]`) as any)?.value||'';return mealsBetween(state,v('from-date'),v('from-type'),v('to-date'),v('to-type')).filter(x=>{const day=ensureWeek(state,planStartOf(state,x.date)).days[x.date];return day&&day[x.type]&&fmMealOn(day,x.type)})}
function guestSheetRefresh(){if(!guestDraft)return;const box=document.getElementById('guest-groups');if(box)box.innerHTML=guestDraft.groups.map((g,i)=>`<div class="guest-group" data-i="${i}"><div class="guest-group-head"><input name="g-name-${i}" data-guest-name="${i}" maxlength="${GUEST_NAME_MAX}" value="${esc(g.name||'')}" placeholder="${esc(tr('Tên (không bắt buộc), ví dụ Nhà anh Tuấn','Name (optional), e.g. Tuan’s family'))}" aria-label="${esc(tr('Tên nhóm khách','Guest group name'))}"><button class="btn icon-step" type="button" data-fm="guest-remove" data-i="${i}" aria-label="${esc(tr('Bỏ nhóm này','Remove this group'))}">×</button></div>${(['adults','kids'] as const).map(k=>`<div class="guest-step"><span><b>${k==='adults'?tr('Người lớn','Adults'):tr('Trẻ em','Children')}</b><small>${k==='adults'?tr('1 suất mỗi người','1 portion each'):tr('½ suất mỗi bé','½ portion each')}</small></span><button class="btn icon-step" type="button" data-fm="guest-step" data-guest-step="-1" data-i="${i}" data-k="${k}" data-d="-1" aria-label="${esc(tr('Bớt','Fewer'))}">−</button><output aria-live="polite">${g[k]||0}</output><button class="btn icon-step" type="button" data-fm="guest-step" data-guest-step="1" data-i="${i}" data-k="${k}" data-d="1" aria-label="${esc(tr('Thêm','More'))}">+</button></div>`).join('')}${guestInviteBlock(g,i)}</div>`).join('');
 const range=guestRange(),per=guestDraft.groups.reduce((n,g)=>n+(g.adults||0)+(g.kids||0)*GUEST_KID_PORTION,0),cooked=range.filter(x=>mealAt(state,x.date,x.type)?.cooked).length;
 const meals=document.getElementById('guest-meals');if(meals)meals.textContent=range.length?tr(`${range.length} bữa: `,`${range.length} meal${range.length>1?'s':''}: `)+range.slice(0,6).map(x=>`${dayShort(x.date)} ${dateLabel(x.date)} ${mealName(x.type).toLowerCase()}`).join(' · ')+(range.length>6?' …':'')+(cooked?tr(` (bỏ qua ${cooked} bữa đã nấu)`,` (${cooked} cooked meal${cooked>1?'s':''} skipped)`):''):tr('Chọn bữa đến trước bữa đi.','Pick the first meal before the last one.');
 const tot=document.getElementById('guest-total');if(tot)tot.textContent=per?tr(`Thêm ${String(+per.toFixed(2)).replace('.',',')} suất mỗi bữa`,`Adds ${+per.toFixed(2)} portions per meal`):tr('Chưa có khách.','No guests yet.');
 const known=document.getElementById('guest-book');if(known){const book=(state.guestBook||[]).filter((b:any)=>!guestDraft!.groups.some(g=>(g.name||'').toLowerCase()===b.name.toLowerCase()));known.innerHTML=book.length?`<p class="hint">${tr('Khách quen — chạm để thêm:','Regular guests — tap to add:')}</p><div class="guest-book">${book.map((b:any)=>`<button class="chip" type="button" data-fm="guest-known" data-name="${esc(b.name)}"><span data-user-content>${esc(b.name)}</span> · ${esc(guestGroupShort(b))}</button>`).join('')}</div>`:''}
 if(typeof (globalThis as any).decorateButtons==='function')(globalThis as any).decorateButtons(document.getElementById('modal-root'))}
function guestSheet(date,type){const m=ensureWeek(state,planStartOf(state,date)).days[date][type];guestDraft={groups:guestGroups(m).length?clone(guestGroups(m)):[{name:'',adults:1,kids:0}]};
 const types=(d:string)=>guestMealTypes(d).map(t=>`<option value="${t}" ${t===type?'selected':''}>${esc(mealName(t))}</option>`).join('');
 modal(tr('Khách','Guests'),`<p class="hint">${tr('Khách được cộng thêm vào suất của nhà mình; giỏ đi chợ tính theo tổng.','Guests are added to your family’s portions; the shopping list uses the total.')}</p>
  ${(()=>{if(guestGroups(m).length)return '';const list=upcomingGuests(sydneyDate(),14).filter(x=>!(x.d===date&&x.t===type)).slice(0,5);return list.length?`<div class="guest-upcoming"><p class="pick-label">${tr('Khách đã hẹn','Guests already planned')}</p><ul class="invite-soon">${list.map(x=>`<li><span>${upcomingGuestLabel(x)}</span><button class="btn small soft" type="button" data-fm="guests" data-date="${esc(x.d)}" data-type="${esc(x.t)}" aria-label="${esc(tr(`Xem khách ${x.g.name||''} · ${mealName(x.t)} ${dateLabel(x.d)}`,`See guests ${x.g.name||''} · ${mealName(x.t)} ${dateLabel(x.d)}`))}">${tr('Xem','See')}</button></li>`).join('')}</ul></div>`:''})()}
  <fieldset class="guest-when"><legend>${tr('Bữa nào?','Which meals?')}</legend><div id="guest-when-picks">${guestWhenHtml({fromDate:date,fromType:type,toDate:date,toType:type})}</div><p class="hint" id="guest-meals" aria-live="polite"></p></fieldset>
  <div id="guest-groups"></div><button class="btn soft" type="button" data-fm="guest-add">${tr('Thêm nhóm khách','Add a guest group')}</button><div id="guest-book"></div><p class="hint guest-total" id="guest-total" aria-live="polite"></p>${m.servings!==null&&m.servings!==undefined?`<p class="hint warn">${tr(`Bữa này đang đặt tay ${String(m.servings).replace('.',',')} suất nên khách không được cộng thêm. Xoá số đặt tay trong “Sửa bữa” để tính tự động.`,`This meal has ${m.servings} portions set by hand, so guests are not added. Clear it in “Edit meal” to count automatically.`)}</p>`:''}`,
  `<button class="btn" type="button" data-action="close-modal">${tr('Đóng','Close')}</button><button class="btn primary" type="button" data-fm="guests-save" data-date="${esc(date)}" data-type="${esc(type)}">${tr('Lưu','Save')}</button>`);guestSheetRefresh()}
// v1.7.13 (owner, 8 Nov 2026: “khu này chọn ngày tháng và bữa phải consistent với cả app design”): the guest sheet picks days
// and meals with the app's own chips (two-line day chips like the week strip, meal chips like the meal tabs) instead of the phone's
// date box and drop-down. The chosen values sit in hidden fields, so the rest of the sheet works as before.
function guestWhenHtml(w:{fromDate:string,fromType:string,toDate:string,toType:string}){const today=sydneyDate(),base=w.fromDate<today?w.fromDate:today,days=Array.from({length:14},(_,i)=>addDays(base,i));
 const dayChips=(name:string,val:string)=>`<div class="pick-days" role="group" aria-label="${esc(name==='from-date'?tr('Ngày đến','Arrival day'):tr('Ngày cuối','Last day'))}">${days.map(d=>`<button type="button" class="pick-day${d===val?' active':''}" data-guest-pick="${name}" data-v="${d}" aria-pressed="${d===val}"><span>${esc(dayShort(d))}</span><strong>${d.slice(8)}</strong><small>${d===today?esc(tr('Hôm nay','Today')):esc(dateLabel(d))}</small></button>`).join('')}</div>`;
 const mealChips=(name:string,date:string,val:string)=>`<div class="pick-meals" role="group">${guestMealTypes(date).map(t=>`<button type="button" class="chip${t===val?' active':''}" data-guest-pick="${name}" data-v="${t}" aria-pressed="${t===val}">${esc(mealName(t))}</button>`).join('')}</div>`;
 return `<input type="hidden" name="from-date" value="${esc(w.fromDate)}"><input type="hidden" name="from-type" value="${esc(w.fromType)}"><input type="hidden" name="to-date" value="${esc(w.toDate)}"><input type="hidden" name="to-type" value="${esc(w.toType)}">
  <p class="pick-label">${tr('Từ','From')}</p>${dayChips('from-date',w.fromDate)}${mealChips('from-type',w.fromDate,w.fromType)}<p class="pick-label">${tr('Đến','To')}</p>${dayChips('to-date',w.toDate)}${mealChips('to-type',w.toDate,w.toType)}`}
function guestWhenRead(){const v=(n:string)=>(document.querySelector(`#modal-root [name="${n}"]`) as any)?.value||'';return{fromDate:v('from-date'),fromType:v('from-type'),toDate:v('to-date'),toType:v('to-type')}}
document.addEventListener('click',e=>{const b=(e.target as any)?.closest?.('#modal-root [data-guest-pick]');if(!b||!guestDraft)return;e.preventDefault();const w:any=guestWhenRead(),k=b.dataset.guestPick;
 if(k==='from-date'){w.fromDate=b.dataset.v;if(w.toDate<w.fromDate)w.toDate=w.fromDate}else if(k==='to-date'){w.toDate=b.dataset.v;if(w.toDate<w.fromDate)w.fromDate=w.toDate}else if(k==='from-type')w.fromType=b.dataset.v;else if(k==='to-type')w.toType=b.dataset.v;
 const fix=(d:string,t:string)=>{const ts=guestMealTypes(d);return ts.includes(t)?t:ts[0]||t};w.fromType=fix(w.fromDate,w.fromType);w.toType=fix(w.toDate,w.toType);
 const box=document.getElementById('guest-when-picks');if(box){const sx=[...box.querySelectorAll('.pick-days')].map((x:any)=>x.scrollLeft);box.innerHTML=guestWhenHtml(w);[...box.querySelectorAll('.pick-days')].forEach((x:any,i)=>x.scrollLeft=sx[i]||0)}guestSheetRefresh()},true);
// v1.7.13 guest invitations (owner, 8 Nov 2026 — plan approved by pop-up; the family has an account, guests answer without one):
// each named group can be sent a link; options: answer deadline, link expiry, how “not sure” counts. Answers come back from the
// server (applyInviteReplies) and the family's phones are told. Times are Sydney time.
const INVITE_DEADLINES:[string,string,string][]=[['2d','2 ngày trước','2 days before'],['1d','1 ngày trước','1 day before'],['morning','Sáng hôm đó','That morning']];
const INVITE_EXPIRY:[string,string,string][]=[['deadline','Sau hạn trả lời','At the deadline'],['meal','Sau bữa','After the meal'],['week','Sau 7 ngày','A week after']];
const INVITE_MAYBE:[string,string,string][]=[['full','Tính đủ','Count fully'],['half','Tính một nửa','Count half'],['none','Không tính','Don’t count']];
const guestInviteDefaults=()=>({deadline:'1d',expiry:'meal',maybe:'full',host:'family'});
const inviteAccount=()=>{const s=(globalThis as any).BEP_SESSION;return s?.mode==='account'&&!!s.household&&s.member?.role!=='viewer'&&s.household?.role!=='viewer'};
// v1.7.14 (owner, 8 Nov 2026: “10gd là nhóm gia đình riêng, nên có option để ghi tên của tôi hay của gia đình mời”): who the invitation is from
const inviteHostNames=()=>{const s=(globalThis as any).BEP_SESSION||{},fam=String(s.household?.name||'').trim(),mid=s.household?.memberId,me=String((mid&&state.members.find((m:any)=>m.id===mid)?.name)||s.account?.name||'').trim();return{fam,me}};
// v1.7.14 (owner: “link invite dài quá”): a short link — /m#<token>; the token stays after # so it never reaches a server log
const inviteLink=(token:string)=>`${location.origin}/m#${token}`;
function inviteHostOf(o:any){const {fam,me}=inviteHostNames();const v=o.host==='me'&&me?me:o.host==='custom'?String(o.hostText||'').trim():fam;return (v||fam||me||'Bếp Nhà').slice(0,60)}
function sydneyAt(date:string,hm:string){const [y,mo,d]=date.split('-').map(Number),[h,mi]=hm.split(':').map(Number),want=Date.UTC(y,mo-1,d,h,mi);let t=want-11*3600000;for(let i=0;i<2;i++){const p:any=Object.fromEntries(new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Sydney',hourCycle:'h23',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).formatToParts(new Date(t)).map((x:any)=>[x.type,x.value]));t+=want-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute)}return new Date(t)}
