// sáng trưa tối và các bữa phụ… sáng trưa tối luôn hiện, xoẹt qua trái hay phải để xoá"): the folded day line is just the
// day, date and a dish count; its "Bữa" button opens the day's meal list to add or remove any meal (snacks included); a
// meal card swiped left or right is removed (the "Bữa" list is the non-gesture way, and brings it back).
// v1.7.8 owner decision (6 Nov 2026): say how the portions are counted — "4 người → 3,15 suất" (children count less; set
// per person in Bếp của nhà mình → Thành viên → Suất / bữa); a meal with a typed portion count says so.
function fmMealPeople(m:any){const date=m?.scheduleDate,type=m?.scheduleType;return state.members.filter((p:any)=>['home','packed','pending'].includes(m.attendance?.[p.id])&&!(date&&typeof deductsBySchedule==='function'&&deductsBySchedule(state,p.id,date,type))).length}
function fmPeoplePortions(m:any,por:string){if(m.servings!==null&&m.servings!==undefined)return`${por} ${tr('suất (đặt tay)','portions (set by hand)')}`;const n=fmMealPeople(m),g=guestCount(m);return`<span title="${esc(tr('Suất của từng người: Bếp của nhà mình → Thành viên → Suất / bữa','Each person’s portion: My kitchen → Members → Portions / meal'))}">${n} ${tr('người','people')}${g?` + ${esc(guestShort(m))}`:''} → ${por} ${tr('suất','portions')}</span>`}
function fmDishCount(day:any){return MEAL_TYPES.filter(t=>fmMealOn(day,t)).reduce((n:number,t:string)=>n+(day[t]?.recipes?.length||0),0)}
function fmDayMarkup(date:string,day:any){if(!fmOpenDays)fmOpenDays=(()=>{try{return new Set(JSON.parse(sessionStorage.getItem('bep-plan-open')||'null')||[])}catch{return new Set<string>()}})();if(!fmClosedDays)fmClosedDays=new Set<string>();fmOpenSeeded=true;
 const today=date===sydneyDate(),open=!fmClosedDays.has(date)&&(fmOpenDays.has(date)||today||date===selectedDate);
 const edit=typeof canEdit!=='function'||canEdit(),batch=(t:string)=>day[t]?.recipes?.some((r:any)=>r.batchId);
 const meals=MEAL_TYPES.filter(t=>fmMealOn(day,t)).map(t=>`<div class="meal-slot" data-slot="${t}"${edit&&!day[t].cooked&&!batch(t)?` data-swipe-meal="${t}" data-date="${date}"`:''}><div class="swipe-under" aria-hidden="true"><span>${esc(tr('Bỏ','Remove'))} ${esc(mealName(t).toLowerCase())}</span><span>${esc(tr('Bỏ','Remove'))} ${esc(mealName(t).toLowerCase())}</span></div><div class="swipe-face">${familyMealMarkup(date,t,day[t])}</div></div>`).join('');
 const n=fmDishCount(day),shown=MEAL_TYPES.filter(t=>fmMealOn(day,t)).length;
 return`<details class="plan-day${today?' is-today':''}" data-plan-day="${date}" ${open?'open':''}><summary class="plan-day-head"><span class="pd-title"><b>${dayName(date)} · ${dateLabel(date)}</b>${today?`<span class="pill">${tr('Hôm nay','Today')}</span>`:''}</span><span class="pd-count">${shown} ${tr('bữa','meals')} · ${n} ${tr('món','dishes')}</span>${edit?`<button type="button" class="btn small pd-meals" data-plan-meal="menu" data-date="${date}" aria-label="${esc(tr(`Thêm hoặc bỏ bữa ngày ${dayName(date)} ${dateLabel(date)}`,`Add or remove meals on ${dayName(date)} ${dateLabel(date)}`))}">${tr('Bữa','Meals')} <span aria-hidden="true">±</span></button>`:''}<span class="pd-chev" aria-hidden="true">▾</span></summary><div class="plan-day-body">${meals||`<p class="hint pd-empty">${tr('Ngày này chưa có bữa nào. Bấm “Bữa ±” để thêm.','No meals on this day. Press “Meals ±” to add one.')}</p>`}</div></details>`}
function fmMealsSheet(date:string){const day=ensureWeek(state,monday(date)).days[date];if(!day)return;
 const row=(t:string)=>{const on=fmMealOn(day,t),m=day[t],k=m?.recipes?.length||0,locked=!!(m?.cooked||m?.recipes?.some((r:any)=>r.batchId));
  return`<label class="pm-row"><input type="checkbox" data-plan-meal-toggle="${t}" data-date="${date}" ${on?'checked':''} ${locked?'disabled':''}><span><b>${esc(mealName(t))}</b>${k?` <small>· ${k} ${tr('món','dishes')}</small>`:''}${locked?` <small>· ${tr('đã nấu / nấu mẻ','cooked / batch')}</small>`:''}</span></label>`};
 modal(`${tr('Bữa trong ngày','Meals on')} ${dayName(date)} · ${dateLabel(date)}`,`<div class="pm-list">${MEAL_TYPES.map(row).join('')}</div><p class="hint">${tr('Bật để thêm bữa, tắt để bỏ. Trong ngày, vuốt một bữa sang trái hoặc phải cũng bỏ bữa đó.','Tick to add a meal, untick to remove it. You can also swipe a meal left or right to remove it.')}</p>`,`<button class="btn primary" type="button" data-action="close-modal">${tr('Xong','Done')}</button>`)}
function fmSetMeal(date:string,t:string,on:boolean,ask=true){const day=ensureWeek(state,monday(date)).days[date],m=day?.[t];if(!m||!MEAL_TYPES.includes(t))return false;const name=mealName(t);
 if(on){if(t==='snack'||t==='snackAm')m.on=true;else delete m.off;fmOpenDays?.add(date);fmClosedDays?.delete(date);save(tr(`Đã thêm ${name.toLowerCase()}.`,`${name} added.`));render();return true}
 if(m.cooked||m.recipes.some((r:any)=>r.batchId))return false;if(ask&&m.recipes.length&&!confirm(tr(`Bỏ ${name.toLowerCase()} ngày ${dateLabel(date)} và ${m.recipes.length} món trong đó?`,`Remove ${name.toLowerCase()} on ${dateLabel(date)} and its ${m.recipes.length} dish(es)?`)))return false;
 if(t==='snack'||t==='snackAm')m.on=false;else m.off=true;m.recipes=[];m.locked=false;save(tr(`Đã bỏ ${name.toLowerCase()}. Thêm lại bằng nút “Bữa ±”.`,`${name} removed. Add it back with “Meals ±”.`));render();return true}
document.addEventListener('change',e=>{const c=(e.target as any)?.closest?.('[data-pantry-deduct]');if(!c)return;state.preferences.pantryDeduct=!!c.checked;save(c.checked?tr('Giỏ trừ đồ đang có trong tủ.','The list takes off pantry stock.'):tr('Giỏ ghi đủ lượng, không trừ tủ.','The list shows full amounts.'));render()});
document.addEventListener('toggle',e=>{const d=e.target as any;if(!d?.dataset?.planDay||!fmOpenDays)return;const k=d.dataset.planDay;if(d.open){fmOpenDays.add(k);fmClosedDays?.delete(k)}else{fmOpenDays.delete(k);fmClosedDays?.add(k)}try{sessionStorage.setItem('bep-plan-open',JSON.stringify([...fmOpenDays]))}catch{}},true);
document.addEventListener('click',e=>{const b=(e.target as any)?.closest?.('[data-plan-meal]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();const date=b.dataset.date,t=b.dataset.type;
 if(b.dataset.planMeal==='menu'){fmMealsSheet(date);return}fmSetMeal(date,t,b.dataset.planMeal==='add')},true);
document.addEventListener('change',e=>{const c=(e.target as any)?.closest?.('[data-plan-meal-toggle]');if(!c)return;const date=c.dataset.date,t=c.dataset.planMealToggle;if(!fmSetMeal(date,t,c.checked)){c.checked=!c.checked;return}fmMealsSheet(date)});
// swipe a meal card left or right (past 35% of its width) to remove that meal; vertical scrolling is left alone
var fmSwipe:any=null;
document.addEventListener('pointerdown',e=>{const pe=e as PointerEvent;if(pe.pointerType==='mouse'&&pe.button!==0)return;const slot=(e.target as any)?.closest?.('[data-swipe-meal]');if(!slot||(e.target as any).closest('input,textarea,select,a'))return;fmSwipe={slot,face:slot.querySelector('.swipe-face'),x:pe.clientX,y:pe.clientY,dx:0,on:false,id:pe.pointerId}},{passive:true});
document.addEventListener('pointermove',e=>{const s=fmSwipe,pe=e as PointerEvent;if(!s||pe.pointerId!==s.id)return;const dx=pe.clientX-s.x,dy=pe.clientY-s.y;
 if(!s.on){if(Math.abs(dy)>12&&Math.abs(dy)>Math.abs(dx)){fmSwipe=null;return}if(Math.abs(dx)<16)return;s.on=true;s.slot.classList.add('swiping');try{s.slot.setPointerCapture?.(pe.pointerId)}catch{}}
 s.dx=dx;s.slot.classList.toggle('swipe-left',dx<0);s.slot.classList.toggle('swipe-ready',Math.abs(dx)>s.slot.offsetWidth*.35);if(s.face)s.face.style.transform=`translateX(${dx}px)`},{passive:true});
function fmSwipeEnd(e:Event){const s=fmSwipe;if(!s)return;fmSwipe=null;if(!s.on)return;const done=Math.abs(s.dx)>s.slot.offsetWidth*.35;
 // the click that follows the swipe's release is not a tap; the next touch starts a real one
 const swallow=(ev:Event)=>{ev.preventDefault();ev.stopPropagation()},stop=()=>{document.removeEventListener('click',swallow,true);document.removeEventListener('pointerdown',stop,true)};document.addEventListener('click',swallow,{capture:true,once:true});document.addEventListener('pointerdown',stop,true);setTimeout(stop,400);
 const reset=()=>{s.slot.classList.remove('swiping','swipe-ready','swipe-left');if(s.face)s.face.style.transform=''};
 if(done&&e.type==='pointerup'){if(!fmSetMeal(s.slot.dataset.date,s.slot.dataset.swipeMeal,false))reset()}else reset()}
document.addEventListener('pointerup',fmSwipeEnd,true);document.addEventListener('pointercancel',fmSwipeEnd,true);
